import math

cand = ["e01", "e08", "e12", "e16", "e27", "e34"]
c7_1  = {'e01':'C','e08':'C','e12':'C','e16':'C','e27':'B','e34':'C'}
c10_2 = {'e01':'A','e08':'B','e12':'B','e16':'C','e27':'A','e34':'C'}

# Exact AH and Norm counts across active days 2..12 (11 days) for the 6 candidates:
# Let's tally from all logs Days 2..12:
ah_counts   = {'e01': 4, 'e08': 2, 'e12': 0, 'e16': 0, 'e27': 2, 'e34': 1}
norm_counts = {'e01': 7, 'e08': 9, 'e12': 7, 'e16': 8, 'e27': 5, 'e34': 11}
ev_counts   = {'e01': (1,8), 'e08': (3,4), 'e12': (2,4), 'e16': (0,5), 'e27': (0,3), 'e34': (0,3)}

def pois_logpmf(k, lam):
    return k * math.log(lam) - lam - math.lgamma(k + 1)

# Note: sum of 11 independent Poissons(lam) has sufficient statistic sum(k) ~ Poisson(11*lam)!
for lam_ah_ben in [0.1263, 0.152]:
    res = {}
    for s in cand:
        ah = ah_counts[s]
        nm = norm_counts[s]
        ev, nev = ev_counts[s]
        ll = (pois_logpmf(nm, 11*0.7) + pois_logpmf(ah, 11*0.3)) - (pois_logpmf(nm, 11*0.9) + pois_logpmf(ah, 11*lam_ah_ben))
        ll += ev * math.log(0.24/0.20) + nev * math.log(0.76/0.80)
        ll += math.log(0.95 if c7_1[s] == 'C' else 0.025)
        ll += math.log(0.95 if c10_2[s] == 'A' else 0.025)
        res[s] = ll
    tot = sum(math.exp(v) for v in res.values())
    print(f"=== lam_ah_benign = {lam_ah_ben} ===")
    for s in sorted(cand, key=lambda x: res[x], reverse=True):
        print(f"  {s}: P = {math.exp(res[s])/tot:.6f}")
